javascript:(function() {
    const canvas = document.getElementById('aniguard-canvas');
    if (!canvas) return alert('Buka minigame AniGuard dulu ya!');

    const STORAGE_KEY = 'aniGuardConfig_v4';
    const defaultConfig = {
        startTime: 21, dynamicMode: true, startIntervalMs: 6000,
        intervalMs: 3500, autoReplay: false, stopMana: 8,
        innerCount: 11, innerRadius: 65, frenzyMana: 25, randomCount: 16
    };

    let savedConfig = localStorage.getItem(STORAGE_KEY);
    window.aniGuardConfig = savedConfig ? Object.assign({}, defaultConfig, JSON.parse(savedConfig)) : defaultConfig;

    function saveConfig() {
        localStorage.setItem(STORAGE_KEY, JSON.stringify(window.aniGuardConfig));
    }

    if (window.aniGuardBotInterval) {
        clearInterval(window.aniGuardBotInterval);
        window.aniGuardBotInterval = null;
    }

    let isBotRunning = false;
    let lastDrawTime = 0;
    let afkWait = false; 

    function drawAdaptiveCustom() {
        const inkEl = document.getElementById('aniguard-ink');
        let currentMana = inkEl ? parseInt(inkEl.innerText) : 100;

        if (currentMana <= window.aniGuardConfig.stopMana) return; 

        const rect = canvas.getBoundingClientRect();
        const cx = rect.width / 2;
        const cy = (rect.height / 2) + 12; 

        function drawDot(x, y) {
            canvas.dispatchEvent(new MouseEvent('mousedown', { bubbles: true, clientX: x, clientY: y }));
            canvas.dispatchEvent(new MouseEvent('mousemove', { bubbles: true, clientX: x + 4, clientY: y + 4 }));
            window.dispatchEvent(new MouseEvent('mouseup', { bubbles: true }));
        }

        const innerCount = window.aniGuardConfig.innerCount;
        const radius = window.aniGuardConfig.innerRadius;
        for (let i = 0; i < innerCount; i++) {
            let angle = (i * (Math.PI * 2 / innerCount));
            drawDot(rect.left + cx + Math.cos(angle) * radius, rect.top + cy + Math.sin(angle) * radius);
        }

        if (currentMana > window.aniGuardConfig.frenzyMana) {
            const edgePoints = [
                {x: 15, y: 15}, {x: rect.width - 15, y: 15},
                {x: 15, y: rect.height - 15}, {x: rect.width - 15, y: rect.height - 15},
                {x: cx, y: 15}, {x: cx, y: rect.height - 15},
                {x: 15, y: cy}, {x: rect.width - 15, y: cy}
            ];
            edgePoints.forEach(p => drawDot(rect.left + p.x, rect.top + p.y));

            const randCount = window.aniGuardConfig.randomCount;
            for (let i = 0; i < randCount; i++) {
                let rx = Math.random() * (rect.width - 40) + 20;
                let ry = Math.random() * (rect.height - 40) + 20;
                drawDot(rect.left + rx, rect.top + ry);
            }
        }
    }

    function masterTick() {
        if (!isBotRunning) return;
        
        let now = Date.now();
        let timeEl = document.getElementById('aniguard-time');
        let currentTime = timeEl ? parseInt(timeEl.innerText) : 0;

        if (window.aniGuardConfig.autoReplay && !afkWait) {
            let completeOverlay = document.getElementById('aniguard-complete');
            let replayBtn = document.getElementById('aniguard-play-again');
            
            if (completeOverlay && completeOverlay.classList.contains('show') && replayBtn) {
                afkWait = true;
                setTimeout(() => {
                    replayBtn.click();
                    lastDrawTime = 0;
                    setTimeout(() => { afkWait = false; }, 500);
                }, 1500); 
                return;
            }
            
            let startOverlay = document.getElementById('aniguard-start');
            let startBtn = document.getElementById('aniguard-start-btn');
            
            if (startOverlay && startOverlay.classList.contains('show') && startBtn) {
                afkWait = true;
                setTimeout(() => {
                    startBtn.click();
                    lastDrawTime = 0;
                    setTimeout(() => { afkWait = false; }, 500);
                }, 500);
                return;
            }
        }

        if (currentTime > window.aniGuardConfig.startTime || currentTime === 0) return; 

        let targetInterval = window.aniGuardConfig.intervalMs;
        let currentInterval = targetInterval;

        if (window.aniGuardConfig.dynamicMode && window.aniGuardConfig.startTime > 0) {
            let progress = 1 - (currentTime / window.aniGuardConfig.startTime); 
            let startInt = window.aniGuardConfig.startIntervalMs;
            currentInterval = startInt - ((startInt - targetInterval) * progress);
        }

        if (now - lastDrawTime >= currentInterval || lastDrawTime === 0) {
            drawAdaptiveCustom();
            lastDrawTime = now;
        }
    }

    let container = document.getElementById('ani-bot-container');
    if (container) container.remove(); 

    container = document.createElement('div');
    container.id = 'ani-bot-container';
    container.style.cssText = 'position:fixed; top:80px; right:20px; z-index:999999; font-family:sans-serif;';

    let btnGroup = document.createElement('div');
    btnGroup.style.cssText = 'display:flex; gap:6px; justify-content:flex-end;';

    let btnMain = document.createElement('button');
    btnMain.innerHTML = '🛡️ Adaptive: OFF';
    btnMain.style.cssText = 'background:#ef4444; color:white; padding:10px 15px; border-radius:8px; font-weight:bold; cursor:pointer; border:2px solid #fff; box-shadow:0 4px 6px rgba(0,0,0,0.3); transition: background 0.2s;';

    let btnSettings = document.createElement('button');
    btnSettings.innerHTML = '⚙️';
    btnSettings.style.cssText = 'background:#334155; color:white; padding:10px 12px; border-radius:8px; font-weight:bold; cursor:pointer; border:2px solid #fff; box-shadow:0 4px 6px rgba(0,0,0,0.3); transition: background 0.2s;';

    btnGroup.appendChild(btnMain);
    btnGroup.appendChild(btnSettings);
    container.appendChild(btnGroup);

    let panel = document.createElement('div');
    panel.style.cssText = 'margin-top:10px; width:260px; max-height: 70vh; overflow-y: auto; background:rgba(15,23,42,0.95); color:white; padding:15px; border-radius:10px; border:1px solid #334155; display:none; flex-direction:column; gap:12px; box-shadow:0 10px 20px rgba(0,0,0,0.6); backdrop-filter:blur(4px);';

    function createInput(label, key, step=1) {
        let wrap = document.createElement('div');
        wrap.style.cssText = 'display:flex; justify-content:space-between; align-items:center; font-size:12px; font-weight:bold; color:#cbd5e1;';
        let lbl = document.createElement('label'); lbl.innerText = label;
        let inp = document.createElement('input');
        inp.type = 'number'; inp.step = step; inp.value = window.aniGuardConfig[key];
        inp.style.cssText = 'width:65px; padding:6px; border-radius:6px; border:1px solid #475569; background:#1e293b; color:#fff; text-align:center; outline:none; font-weight:bold;';
        inp.onchange = (e) => { 
            window.aniGuardConfig[key] = parseInt(e.target.value); 
            saveConfig();
        };
        wrap.appendChild(lbl); wrap.appendChild(inp);
        return wrap;
    }

    function createToggle(label, key) {
        let wrap = document.createElement('div');
        wrap.style.cssText = 'display:flex; justify-content:space-between; align-items:center; font-size:12px; font-weight:bold; color:#cbd5e1;';
        let lbl = document.createElement('label'); lbl.innerText = label;
        let inp = document.createElement('input');
        inp.type = 'checkbox'; inp.checked = window.aniGuardConfig[key];
        inp.style.cssText = 'width:18px; height:18px; cursor:pointer; accent-color:#3b82f6;';
        inp.onchange = (e) => { 
            window.aniGuardConfig[key] = e.target.checked; 
            saveConfig();
        };
        wrap.appendChild(lbl); wrap.appendChild(inp);
        return wrap;
    }

    function addHeader(text) {
        let h = document.createElement('div');
        h.innerText = text;
        h.style.cssText = 'font-size:11px; text-transform:uppercase; color:#94a3b8; border-bottom:1px solid #334155; padding-bottom:4px; margin-top:4px;';
        panel.appendChild(h);
    }

    addHeader('Waktu & Interval');
    panel.appendChild(createInput('Mulai di (Detik)', 'startTime'));
    panel.appendChild(createToggle('⚡ Mode Dinamis', 'dynamicMode'));
    panel.appendChild(createInput('Interval Awal (ms)', 'startIntervalMs', 100));
    panel.appendChild(createInput('Interval Akhir (ms)', 'intervalMs', 100));

    addHeader('Fitur AFK');
    panel.appendChild(createToggle('🤖 Auto-Replay (AFK)', 'autoReplay'));

    addHeader('Manajemen Mana');
    panel.appendChild(createInput('Setop Frenzy (%)', 'frenzyMana'));
    panel.appendChild(createInput('Setop Total (%)', 'stopMana'));

    addHeader('Formasi Titik');
    panel.appendChild(createInput('Titik Lingkaran', 'innerCount'));
    panel.appendChild(createInput('Radius Lingkaran', 'innerRadius'));
    panel.appendChild(createInput('Jumlah Ranjau', 'randomCount'));

    let btnClose = document.createElement('button');
    btnClose.innerHTML = '✔ Simpan / Tutup';
    btnClose.style.cssText = 'margin-top:8px; background:#3b82f6; color:white; padding:10px; border:none; border-radius:6px; font-weight:bold; cursor:pointer;';
    btnClose.onclick = () => {
        panel.style.display = 'none';
        btnSettings.style.background = '#334155';
    };
    panel.appendChild(btnClose);
    container.appendChild(panel);
    document.body.appendChild(container);

    btnSettings.onclick = () => {
        let isClosed = panel.style.display === 'none';
        panel.style.display = isClosed ? 'flex' : 'none';
        btnSettings.style.background = isClosed ? '#3b82f6' : '#334155';
    };

    btnMain.onclick = () => {
        isBotRunning = !isBotRunning;
        if (isBotRunning) {
            btnMain.style.background = '#22c55e';
            btnMain.innerHTML = '🛡️ Adaptive: ON';
            lastDrawTime = 0; 
            afkWait = false;
            window.aniGuardBotInterval = setInterval(masterTick, 200);
        } else {
            btnMain.style.background = '#ef4444';
            btnMain.innerHTML = '🛡️ Adaptive: OFF';
            clearInterval(window.aniGuardBotInterval);
            window.aniGuardBotInterval = null;
        }
    };
})();